export const PORTFOLIO_ASSET_MODE='UPBIT_BTC_PORTFOLIO',PORTFOLIO_SIMULATION_VERSION='canonical-btc-portfolio-simulation-v1';
const DAY=86400000,clone=structuredClone,iso=v=>typeof v==='string'&&Number.isFinite(Date.parse(v))&&new Date(v).toISOString()===v,at=t=>new Date(t).toISOString(),round=v=>Math.round(v*1e8)/1e8;
const check=(v,code,message)=>{if(!v)throw Object.assign(new Error(message),{code,status:409});};
export function validatePortfolioSimulationConfig(input,bundle,manifest){
 assertMindDocument(manifest);compileStrategyGraph(manifest.data.strategyPlan.graph);const graph=manifest.data.strategyPlan.graph,scope=manifest.data.strategyPlan.scope;
 check(manifest.data.strategyPlan.status==='APPROVED'&&manifest.data.strategyPlan.approval.enabled===true,'PORTFOLIO_GRAPH_REQUIRED','실험에 사용할 그래프를 승인하세요.');
 check(input.assetMode===PORTFOLIO_ASSET_MODE&&input.datasetId===bundle.index.id&&input.mode==='GRAPH_CANONICAL','PORTFOLIO_SIMULATION_MODE','BTC 다종목 자료와 노드 전략을 선택하세요.');
 check(scope.universe==='MIND_UNIVERSE'&&scope.timeframe==='1d'&&scope.quoteCurrency==='BTC'&&graph.nodes.find(n=>n.id===graph.outputNodeId)?.config.sizing==='TARGET_WEIGHTS','PORTFOLIO_GRAPH_REQUIRED','일봉 종목 선별·비중 배분·위험 한도·주문을 연결하세요.');
 check(!graph.nodes.some(n=>n.type==='VIBE'),'PORTFOLIO_JEV_NODE','다종목 비중 판단에는 JEV 질문 노드를 연결하세요.');
 check(input.mindId===manifest.scope.profileId&&iso(input.startAt)&&iso(input.endAt)&&input.startAt<input.endAt&&Date.parse(input.startAt)%DAY===0&&Date.parse(input.endAt)%DAY===0&&input.startAt>=bundle.index.coverage.startAt&&input.endAt<=bundle.index.coverage.endAt,'PORTFOLIO_PERIOD','보관된 확정 일봉 범위에서 UTC 일자를 선택하세요.');
 check(Number.isFinite(input.initialCash)&&input.initialCash>=.00005&&input.initialCash<=1000&&([[10,5],[25,15]].some(([fee,slip])=>(input.feeBps??10)===fee&&(input.slippageBps??5)===slip)),'PORTFOLIO_COST_POLICY','BTC 자금과 기본 비용(10bp·5bp) 또는 비용 스트레스(25bp·15bp)를 선택하세요.');
 check(Number.isInteger(input.maxJevCalls??0)&&(input.maxJevCalls??0)>=0&&(input.maxJevCalls??0)<=JEV_EXECUTION_CALL_LIMIT&&(!graphRequiresJev(graph)||input.optInJev===true&&input.maxJevCalls>0),'SIMULATION_JEV_CONSENT','JEV 질문의 호출 예산에 동의하세요.');
 const available=new Set(bundle.index.universe.instrumentIds),ids=manifest.data.universe.instrumentIds;
 check(ids.length>0&&ids.every(id=>available.has(id)&&getInstrument(id).quoteCurrency==='BTC'),'PORTFOLIO_UNIVERSE','고정 자료에 포함된 업비트 BTC 종목으로 투자 범위를 구성하세요.');
 check(ids.every(id=>minimumMindNotional(manifest,getInstrument(id))===.00005),'PORTFOLIO_MINIMUM','BTC 최소 주문 금액 0.00005를 정책에 설정하세요.');
 return {assetMode:PORTFOLIO_ASSET_MODE,datasetId:input.datasetId,mindId:input.mindId,name:input.name??manifest.data.name+' 다종목 비교',mode:'GRAPH_CANONICAL',startAt:input.startAt,endAt:input.endAt,initialCash:input.initialCash,feeBps:input.feeBps??10,slippageBps:input.slippageBps??5,optInJev:input.optInJev===true,maxJevCalls:input.maxJevCalls??0,participationCap:.001,benchmarkSelection:{id:'CUSTOM',startAt:input.startAt,endAt:input.endAt}};
}
export function portfolioSource(bundle){return {assetMode:PORTFOLIO_ASSET_MODE,datasetId:bundle.index.id,datasetSha256:bundle.indexSha256,provider:'upbit',venue:'Upbit',quoteCurrency:'BTC',timeframe:'1d',instruments:clone(bundle.index.universe.instrumentIds),startAt:bundle.index.coverage.startAt,endAt:bundle.index.coverage.endAt,rawDatasetPath:'/api/workspace/simulations/report',availabilityPolicy:'CLOSED_DAILY_PREFIX_ONLY',universeSelection:clone(bundle.index.universe),limitations:clone(bundle.index.limitations??[])};}
export function portfolioAccountSummary(a){return {cash:a.cash,equity:a.equity,holdingsValue:a.holdingsValue,feesPaid:a.feesPaid,realizedPnl:a.realizedPnl,unrealizedPnl:a.unrealizedPnl,netReturn:a.netReturn,quoteCurrency:'BTC',positions:clone(a.positions),asOf:a.updatedAt};}
export function stripPortfolioAccount(a){const {ledger,receipts,events,...body}=a;return body;}
export function restorePortfolioAccount(core,{fills=[],decisions=[]}={}){const account={...clone(core.paperAccount),ledger:fills.map(f=>clone(f.ledgerEntry)),receipts:decisions.flatMap(d=>clone(d.paperReceipts??[])),events:decisions.flatMap(d=>clone(d.paperEvents??[]))};check(hashInputPackage(account)===core.paperAccountHash&&!validateMindPaperAccount(account).length,'PORTFOLIO_ACCOUNT_HASH','저장된 체결·영수증·계좌 원장을 대조하세요.');return account;}
export function createPortfolioSimulation(bundle,input,{id,manifest,now}){
 const config=validatePortfolioSimulationConfig(input,bundle,manifest),account=(config.feeBps===25?createHistoricalMindPaperAccount:createMindPaperAccount)({id:'portfolio-'+id,profileId:config.mindId,quoteCurrency:'BTC',initialCash:config.initialCash,now:config.startAt,feeBps:config.feeBps,slippageBps:config.slippageBps}),total=(Date.parse(config.endAt)-Date.parse(config.startAt))/DAY;
 return {schemaVersion:1,contractVersion:PORTFOLIO_SIMULATION_VERSION,id,mode:config.mode,status:'CREATED',config,manifest:clone(manifest),pins:{manifestId:manifest.id,manifestHash:mindDocumentHash(manifest),graphHash:strategyGraphHash(manifest.data.strategyPlan.graph),datasetHash:bundle.indexSha256,universeHash:hashInputPackage(manifest.data.universe.instrumentIds),executionContractVersion:'PORTFOLIO_HISTORICAL_FILL_V1'},coverage:{totalDecisionFrames:total,timeframe:'1d',instrumentIds:clone(manifest.data.universe.instrumentIds),startAt:config.startAt,endAt:config.endAt},cursor:0,sequence:0,account:portfolioAccountSummary(account),paperAccount:stripPortfolioAccount(account),paperAccountHash:hashInputPackage(account),lastRebalancedAt:null,lastRebalanceEvaluationAt:null,totals:{decisionCount:0,warmupCount:0,jevCalls:0,tradeCount:0,buyCount:0,sellCount:0,winningExits:0,losingExits:0,turnover:0,slippagePaid:0,peakEquity:config.initialCash,maxDrawdown:0,staleValuationFrames:0,blockedOrders:0},rowsCounts:{decisions:0,fills:0,curve:0},createdAt:now,updatedAt:now};
}
export function nextPortfolioFrame(core){if(core.cursor>=core.coverage.totalDecisionFrames)return null;const time=Date.parse(core.config.startAt)+core.cursor*DAY;return {sequence:core.cursor+1,asOf:at(time),decisionAt:at(time),nextCloseAt:at(time+DAY)};}
const sourceRows=(bundle,id)=>bundle.datasets.find(d=>'crypto:upbit:'+d.market===id)?.rows??[];
const bar=(r)=>({openTime:r.time,closeTime:r.closeTime,open:r.open,high:r.high,low:r.low,close:r.close,volume:r.volume,quoteVolume:r.quoteVolume});
const markQuote=(id,r,key,time)=>({instrumentId:id,currency:'BTC',price:r[key],asOf:time,receivedAt:time,source:key==='open'?'UPBIT_DAILY_NEXT_OPEN':'UPBIT_DAILY_CLOSE',priceBasis:key==='open'?'HISTORICAL_NEXT_OPEN':'HISTORICAL_CLOSE',executionAllowed:false,sourceHash:r.sourcePageHash});
export function preparePortfolioSimulationFrame({core,account,bundle,frame=nextPortfolioFrame(core)}){
 check(frame&&bundle.indexSha256===core.pins.datasetHash,'PORTFOLIO_SOURCE','실험의 고정 자료와 다음 일봉을 확인하세요.');
 const historyBars=Math.min(1000,Math.max(2,...core.manifest.data.strategyPlan.graph.nodes.flatMap(n=>[n.config.minHistoryBars??0,(n.config.volatilityBars??0)+1,(n.config.normalizationLookback??0)+1,...(n.config.terms??[]).map(t=>t.lookback+1),...(n.config.conditions??[]).map(t=>t.lookback+1)]))),ids=core.manifest.data.universe.instrumentIds,items=ids.map(instrumentId=>{const rows=sourceRows(bundle,instrumentId).filter(r=>r.closeTime<=frame.asOf).slice(-historyBars);return {instrumentId,bars:rows.map(bar),quoteVolume:rows.at(-1)?.quoteVolume??0,warning:false};}),quotes=[];
 for(const p of account.positions){const r=sourceRows(bundle,p.instrumentId).find(r=>r.closeTime===frame.asOf);if(r)quotes.push(markQuote(p.instrumentId,r,'close',frame.asOf));}
 const marked=quotes.length===account.positions.length?markMindPaperAccount(account,{quotes,now:frame.asOf}):clone(account),portfolio={profileId:core.config.mindId,quoteCurrency:'BTC',asOf:frame.asOf,equity:marked.equity,cashWeight:marked.cash/marked.equity,weights:marked.positions.map(p=>({instrumentId:p.instrumentId,weight:p.marketValue/marked.equity})),lastRebalancedAt:core.lastRebalanceEvaluationAt??core.lastRebalancedAt,universeHash:core.pins.universeHash};
 // Round8 account marks can differ from raw component sums by one satoshi.
 portfolio.cashWeight=Math.max(0,1-portfolio.weights.reduce((s,p)=>s+p.weight,0));
 const value={contractVersion:'portfolio-candidate-set-v1',profileId:core.config.mindId,quoteCurrency:'BTC',timeframe:'1d',asOf:frame.asOf,universeHash:core.pins.universeHash,items},inputs={};
 for(const n of core.manifest.data.strategyPlan.graph.nodes)if(n.type==='INPUT'&&n.config.kind==='ASSET_SET')inputs[n.id]={ready:true,asOf:frame.asOf,availableAt:frame.asOf,sourceRefs:[{id:core.config.datasetId,contentHash:core.pins.datasetHash,sourceRef:'upbit://archive/'+core.config.datasetId}],value:clone(value)};
 for(const n of core.manifest.data.strategyPlan.graph.nodes)if(n.type==='INPUT'&&n.config.kind==='CONTEXT'&&n.id==='portfolio-state')inputs[n.id]={ready:true,asOf:frame.asOf,availableAt:frame.asOf,sourceRefs:[{id:account.id,contentHash:hashInputPackage(portfolio),sourceRef:'simulation://'+core.id+'/account/'+frame.sequence}],value:clone(portfolio)};
 for(const n of core.manifest.data.strategyPlan.graph.nodes)if(n.type==='INPUT'&&n.config.kind==='POSITION')inputs[n.id]=resolvePositionInput({binding:n.config,account:marked,profileId:core.config.mindId,asOf:frame.asOf});
 const executionContext={profileId:core.config.mindId,portfolio,researchProjection:'BLIND_PORTFOLIO_HISTORY_V1'},evaluation={asOf:frame.asOf,source:{datasetSha256:core.pins.datasetHash},modules:[],executionInputs:inputs,executionContext,decisionInputs:{},trigger:'closed_bar'};
 evaluation.graphEvaluation=evaluateStrategyGraph(core.manifest.data.strategyPlan.graph,[],{asOf:frame.asOf,sourceHash:core.pins.datasetHash,inputs,context:executionContext,trigger:'closed_bar'});evaluation.outputHash=strategyEvaluationHash(evaluation);
 return {frame,account:marked,request:{state:{strategyEvaluation:evaluation}},inputHash:hashInputPackage({inputs,executionContext}),sourceHash:core.pins.datasetHash};
}
export function applyPortfolioSimulationFrame({core,account,bundle,prepared,evaluation=prepared.request.state.strategyEvaluation,jevCallCount=0,now}){
 const frame=prepared.frame,graph=core.manifest.data.strategyPlan.graph,original=prepared.request.state.strategyEvaluation;
 check(evaluation.asOf===frame.asOf&&hashInputPackage(evaluation.executionInputs)===hashInputPackage(original.executionInputs)&&hashInputPackage(evaluation.executionContext)===hashInputPackage(original.executionContext),'PORTFOLIO_FRAME_BINDING','동일 시점의 종목·잔고 입력을 유지하세요.');
 const replay=evaluateStrategyGraph(graph,[],{asOf:frame.asOf,sourceHash:core.pins.datasetHash,inputs:original.executionInputs,decisions:evaluation.decisionInputs??{},context:original.executionContext,trigger:'closed_bar',...(evaluation.simulationResponsePolicy?{simulationResponsePolicy:evaluation.simulationResponsePolicy}:{})});check(replay.outputHash===evaluation.graphEvaluation.outputHash,'PORTFOLIO_GRAPH_PROOF','저장된 노드 판정과 종목별 목표 비중을 재생하세요.');
 const output=replay.output,next=clone(core),before=account,allocations=[],oldLedger=account.ledger.length,oldReceipts=account.receipts.length,oldEvents=account.events.length;account=clone(prepared.account);if(output.ready&&replay.trace.some(row=>row.type==='REBALANCE'&&['REBALANCE_DUE','WEIGHT_DIFFERENCE_BELOW_MINIMUM'].includes(row.reason)))next.lastRebalanceEvaluationAt=frame.asOf;
 const opens=new Map(core.manifest.data.universe.instrumentIds.map(id=>[id,sourceRows(bundle,id).find(r=>r.time===frame.asOf&&r.closeTime===frame.nextCloseAt)])),heldGap=account.positions.some(p=>!opens.get(p.instrumentId));
 if(output.ready&&output.kind==='TARGET_WEIGHTS'&&output.orderAllowed&&output.value.rebalanceDue&&!heldGap){
  account=markMindPaperAccount(account,{quotes:account.positions.map(p=>markQuote(p.instrumentId,opens.get(p.instrumentId),'open',frame.asOf)),now:frame.asOf});
  const currentWeights=new Map(account.positions.map(p=>[p.instrumentId,p.marketValue/account.equity])),targets=[...output.value.targets].sort((a,b)=>(a.targetWeight-(currentWeights.get(a.instrumentId)??0))-(b.targetWeight-(currentWeights.get(b.instrumentId)??0))||a.instrumentId.localeCompare(b.instrumentId));
  for(const target of targets){const r=opens.get(target.instrumentId),p=account.positions.find(p=>p.instrumentId===target.instrumentId),weight=p?p.marketValue/account.equity:0;if(Math.abs(target.targetWeight-weight)<1e-12)continue;
   if(!r){allocations.push({...target,status:'BLOCKED',reason:'NEXT_DAILY_CANDLE_MISSING'});continue;}
   const previous=sourceRows(bundle,target.instrumentId).find(r=>r.closeTime===frame.asOf);if(!previous){allocations.push({...target,status:'BLOCKED',reason:'OBSERVABLE_VOLUME_MISSING'});continue;}
   const run={id:core.id+'-'+frame.sequence+'-'+target.instrumentId,profileId:core.config.mindId,instrumentId:target.instrumentId,manifestId:core.manifest.id,manifestHash:core.pins.manifestHash,asOf:frame.asOf,decisionAt:frame.asOf,mode:'PORTFOLIO_HISTORICAL_SIMULATION',decision:{action:target.targetWeight>weight?'buy':'sell',stance:'normal',confidence:1,targetWeight:target.targetWeight,evidenceRefs:[core.pins.graphHash],asOf:frame.asOf,decisionAt:frame.asOf},risk:{allowed:true,reasons:[]}},quote=markQuote(target.instrumentId,r,'open',frame.asOf),historical={contractVersion:'PORTFOLIO_HISTORICAL_FILL_V1',timeframe:'1d',sourceHash:r.sourcePageHash,asOf:frame.asOf,nextOpenAt:r.time,volume:previous.volume,volumeAsOf:previous.closeTime,volumeSourceHash:previous.sourcePageHash,participationCap:core.config.participationCap,targets:output.value};
   const result=executeHistoricalMindPaperTarget(account,run,{manifest:core.manifest,instrument:getInstrument(target.instrumentId),quote,historical,now:frame.asOf});if(result.ok)account=result.account;
   allocations.push({...target,action:run.decision.action,status:result.ok?result.outcome:'BLOCKED',reason:result.reasons[0]?.code??null,runId:run.id,executionId:result.execution?.id??null,volumeEvidence:{asOf:previous.closeTime,sourceHash:previous.sourcePageHash,volume:previous.volume,participationCap:core.config.participationCap}});
  }
  
 }
 const closeQuotes=[];for(const p of account.positions){const r=opens.get(p.instrumentId);if(r)closeQuotes.push(markQuote(p.instrumentId,r,'close',frame.nextCloseAt));}
 if(closeQuotes.length===account.positions.length)account=markMindPaperAccount(account,{quotes:closeQuotes,now:frame.nextCloseAt});const stale=account.positions.filter(p=>p.priceAsOf!==frame.nextCloseAt).map(p=>p.instrumentId),fills=account.ledger.slice(oldLedger).map((entry,i)=>({sequence:core.rowsCounts.fills+i+1,frameSequence:frame.sequence,at:entry.at,asOf:entry.at,action:entry.side,instrumentId:entry.instrumentId,quantity:entry.quantity,price:entry.fillPrice,fee:entry.fee,realizedPnl:entry.realizedPnl,ledgerEntry:clone(entry)}));
 if(fills.length)next.lastRebalancedAt=frame.asOf;next.cursor++;next.sequence=frame.sequence;next.status=next.cursor===next.coverage.totalDecisionFrames?'COMPLETED':'RUNNING';next.updatedAt=now;next.paperAccount=stripPortfolioAccount(account);next.paperAccountHash=hashInputPackage(account);next.account=portfolioAccountSummary(account);next.rowsCounts={decisions:core.rowsCounts.decisions+1,fills:core.rowsCounts.fills+fills.length,curve:core.rowsCounts.curve+1};
 const t=next.totals;t.decisionCount++;t.warmupCount+=Number(!output.ready);t.jevCalls+=jevCallCount;t.staleValuationFrames+=Number(stale.length>0);t.blockedOrders+=allocations.filter(a=>a.status==='BLOCKED').length;t.peakEquity=Math.max(t.peakEquity,account.equity);t.maxDrawdown=Math.max(t.maxDrawdown,(t.peakEquity-account.equity)/t.peakEquity);
 for(const f of fills){t.tradeCount++;t[f.action==='buy'?'buyCount':'sellCount']++;t.turnover+=f.ledgerEntry.gross/core.config.initialCash;t.slippagePaid=round(t.slippagePaid+f.ledgerEntry.slippageCost);if(f.action==='sell')t[f.realizedPnl>0?'winningExits':'losingExits']++;}
 const decision={sequence:frame.sequence,asOf:frame.asOf,action:output.orderAllowed?'rebalance':'hold',evaluationStatus:output.ready?'READY':'WARMUP',targets:clone(output.value??null),allocations,jevCalled:jevCallCount>0,jevCallCount,graphHash:core.pins.graphHash,outputHash:replay.outputHash,inputHash:prepared.inputHash,heldGap,staleValuationInstrumentIds:stale,paperReceipts:account.receipts.slice(oldReceipts),paperEvents:account.events.slice(oldEvents)};
 return {state:next,account,rows:{decisions:[decision],fills,curve:[{sequence:frame.sequence,asOf:frame.nextCloseAt,at:frame.nextCloseAt,equity:account.equity,cash:account.cash,holdingsValue:account.holdingsValue,netReturn:account.netReturn,benchmarkEquity:core.config.initialCash,benchmarkReturn:0,drawdown:(t.peakEquity-account.equity)/t.peakEquity,positions:clone(account.positions),staleValuationInstrumentIds:stale}]},evaluation:clone(evaluation)};
}
export function finalizePortfolioReport(core){const a=core.account,t=core.totals,c=core.config,ret=a.equity/c.initialCash-1,metrics={initialEquity:c.initialCash,finalEquity:a.equity,totalReturn:ret,totalReturnPct:ret*100,CAGR:Math.pow(a.equity/c.initialCash,365/Math.max(1,core.cursor))-1,maxDrawdown:t.maxDrawdown,tradeCount:t.tradeCount,buyCount:t.buyCount,sellCount:t.sellCount,realizedWinRate:t.sellCount?t.winningExits/t.sellCount:null,feesPaid:a.feesPaid,slippagePaid:t.slippagePaid,totalCosts:a.feesPaid+t.slippagePaid,turnover:t.turnover,realizedPnl:a.realizedPnl,unrealizedPnl:a.unrealizedPnl,quoteCurrency:'BTC'},btcHold={id:'BTC_HOLD',initialEquity:c.initialCash,finalEquity:c.initialCash,totalReturn:0,maxDrawdown:0,feesPaid:0,slippagePaid:0,tradeCount:0};return {schemaVersion:1,contractVersion:PORTFOLIO_SIMULATION_VERSION,simulationId:core.id,status:core.status,config:clone(c),pins:clone(core.pins),coverage:clone(core.coverage),metrics,benchmarks:{btcHold,cash:clone(btcHold)},excessReturn:{btcHold:ret},account:clone(a),rowsCounts:clone(core.rowsCounts),jevCalls:t.jevCalls,quality:{staleValuationFrames:t.staleValuationFrames,blockedOrders:t.blockedOrders},assumptions:{numeraire:'BTC',signal:'CONFIRMED_DAILY_PREFIX',fill:'NEXT_CONTIGUOUS_DAILY_OPEN',liquidity:'PREVIOUS_CLOSED_DAY_VOLUME_PROXY',participationCap:c.participationCap,costPolicy:core.paperAccount.costPolicy.version,feeBps:c.feeBps,slippageBps:c.slippageBps,minimumOrderBTC:.00005,missingCandles:'PRESERVED_NO_FILL',orderbook:'HISTORICAL_DAILY_DATA',survivorship:'CURRENT_OFFICIAL_MARKET_LIST_INTERSECTION'},createdAt:core.createdAt,completedAt:core.updatedAt};}
